// Ogg Opus bytes of an earcon by name (needs_you, approved, denied, done, error, chat_switch).
inline std::string_view Get(std::string_view name) {
    if (name == "needs_you") return {reinterpret_cast<const char*>(kNeedsYou), sizeof(kNeedsYou)};
    if (name == "approved") return {reinterpret_cast<const char*>(kApproved), sizeof(kApproved)};
    if (name == "denied") return {reinterpret_cast<const char*>(kDenied), sizeof(kDenied)};
    if (name == "done") return {reinterpret_cast<const char*>(kDone), sizeof(kDone)};
    if (name == "error") return {reinterpret_cast<const char*>(kError), sizeof(kError)};
    if (name == "chat_switch") return {reinterpret_cast<const char*>(kChatSwitch), sizeof(kChatSwitch)};
    return {};
}

